#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <string.h>

/* LAPACK dgeev: real eigenvalues */
extern void dgeev_(char *jobvl, char *jobvr, int *n, double *a, int *lda,
                   double *wr, double *wi, double *vl, int *ldvl,
                   double *vr, int *ldvr, double *work, int *lwork,
                   int *info);

/* LAPACK zgeev: complex eigenvalues */
extern void zgeev_(char *jobvl, char *jobvr, int *n, double *a, int *lda,
                   double *w, double *vl, int *ldvl,
                   double *vr, int *ldvr, double *work, int *lwork,
                   double *rwork, int *info);

static PyObject* py_find_dominant_eigenvalue_and_eigenvector(PyObject* self, PyObject* args) {
    PyObject* py_A;
    if (!PyArg_ParseTuple(args, "O", &py_A)) return NULL;

    PyArrayObject* A_arr = (PyArrayObject*)py_A;
    if (PyArray_NDIM(A_arr) != 2) {
        PyErr_SetString(PyExc_ValueError, "A must be 2D");
        return NULL;
    }

    npy_intp n = PyArray_DIM(A_arr, 0);
    if (PyArray_DIM(A_arr, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "A must be square");
        return NULL;
    }

    if (PyArray_TYPE(A_arr) != NPY_FLOAT64) {
        PyErr_SetString(PyExc_ValueError, "A must be float64");
        return NULL;
    }

    double* A = (double*)PyArray_DATA(A_arr);

    /* Allocate workspace */
    int lwork = 4 * n;
    double* work = (double*)malloc(lwork * sizeof(double));
    double* wr = (double*)malloc(n * sizeof(double));
    double* wi = (double*)malloc(n * sizeof(double));
    double* vr = (double*)malloc(n * n * sizeof(double));
    int info;

    /* Copy A into a working buffer (dgeev may modify it) */
    double* Awork = (double*)malloc(n * n * sizeof(double));
    memcpy(Awork, A, n * n * sizeof(double));

    char jobvl = 'N';
    char jobvr = 'V';
    int lda = n;
    int ldvl = n;
    int ldvr = n;

    dgeev_(&jobvl, &jobvr, &n, Awork, &lda, wr, wi, NULL, &ldvl, vr, &ldvr, work, &lwork, &info);

    /* Find dominant eigenvalue (largest magnitude) */
    int idx = 0;
    double max_mag = 0.0;
    for (int i = 0; i < n; i++) {
        double mag;
        if (wi[i] == 0.0) {
            mag = (wr[i] < 0) ? -wr[i] : wr[i];
        } else {
            mag = sqrt(wr[i]*wr[i] + wi[i]*wi[i]);
        }
        if (mag > max_mag) {
            max_mag = mag;
            idx = i;
        }
    }

    /* Build complex eigenvalue */
    double ev_real = wr[idx];
    double ev_imag = wi[idx];

    /* Build eigenvector column */
    double* eigvec = (double*)malloc(2 * n * sizeof(double));
    for (int i = 0; i < n; i++) {
        eigvec[2*i]   = vr[i + idx * n];
        eigvec[2*i+1] = (wi[idx] == 0.0) ? 0.0 : vr[i + idx * n];
    }

    /* Create numpy arrays for output */
    npy_intp ev_shape = 1;
    PyObject* ev_arr = PyArray_SimpleNewFromData(1, &ev_shape, NPY_COMPLEX128, &ev_real);
    npy_intp vec_shape = n;
    PyObject* vec_arr = PyArray_SimpleNewFromData(1, &vec_shape, NPY_COMPLEX128, eigvec);

    /* Free memory */
    free(Awork);
    free(work);
    free(wr);
    free(wi);
    free(vr);
    /* Don't free eigvec - it's owned by vec_arr */

    PyObject* result = Py_BuildValue("(OO)", ev_arr, vec_arr);
    Py_DECREF(ev_arr);
    Py_DECREF(vec_arr);
    return result;
}

static PyMethodDef EigenMethods[] = {
    {"find_dominant_eigenvalue_and_eigenvector", py_find_dominant_eigenvalue_and_eigenvector, METH_VARARGS, "Find dominant eigenvalue and eigenvector"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef eigenmodule = {
    PyModuleDef_HEAD_INIT, "eigen_c", NULL, -1, EigenMethods
};

PyMODINIT_FUNC PyInit_eigen_c(void) {
    import_array();
    return PyModule_Create(&eigenmodule);
}
CEOF

